currentUI.box=(c,x,y,w,h,fill='#293640')=>{c.fillStyle=fill;c.fillRect(x,y,w,h);c.fillStyle=currentUI.settings.lineColor;c.fillRect(x,y,w,1);c.fillRect(x,y+h-1,w,1);c.fillRect(x,y,1,h);c.fillRect(x+w-1,y,1,h)};
