currentUI.resource=(c,label,value)=>{currentUI.box(c,198,161,115,14,'#11171c');const s=currentUI.settings;currentUI.clip(c,199,162,113,12,()=>{currentUI.text(c,label,199+s.resourcePadding,160+s.resourceOffset);currentUI.text(c,value,312-s.resourcePadding,160+s.resourceOffset,'right')})};
