currentUI.patterns={left:['00100','01100','11111','01100','00100'],up:['00100','01110','11111','00100','00100'],right:['00100','00110','11111','00110','00100'],down:['00100','00100','11111','01110','00100'],sword:['000001','000011','000110','001100','111000','010000'],eye:['0011100','0100010','1001001','0100010','0011100']};
currentUI.controls=c=>{for(const [kind,x,y]of [['left',118,161],['up',145,161],['right',172,161],['sword',118,183],['down',145,183],['eye',172,183]]){currentUI.box(c,x,y,x===172?25:26,21,['eye','sword'].includes(kind)?'#655848':'#293640');const rows=currentUI.patterns[kind],left=Math.round(x+(26-rows[0].length*2)/2),top=Math.round(y+(21-rows.length*2)/2);c.fillStyle=currentUI.settings.textColor;rows.forEach((r,yy)=>[...r].forEach((v,xx)=>{if(v==='1')c.fillRect(left+xx*2,top+yy*2,2,2)}))}};
currentUI.paint=(c,im,p,n)=>{if(p.mode==='FIT'){const ratio=Math.min(n.w/im.width,n.h/im.height),w=Math.round(im.width*ratio),h=Math.round(im.height*ratio);c.drawImage(im,Math.round(n.x+(n.w-w)/2),Math.round(n.y+(n.h-h)/2),w,h)}else c.drawImage(im,Math.round(n.x),Math.round(n.y),Math.round(n.w),Math.round(n.h))};
currentUI.layout=(c,key)=>{const layout=currentUI.layouts.find(s=>s.key===key);for(const n of layout.items){if(n.type==='TEXT'||key==='title'&&(n.name.includes('НАЧАТЬ ИГРУ')||n.id.includes('67:1537')))continue;for(const p of n.fills||[]){if(p.type==='IMAGE'){const im=currentUI.assets[p.hash];currentUI.paint(c,im,p,n)}else if(p.type==='SOLID'){const col=p.color;c.fillStyle='#'+[col.r,col.g,col.b].map(v=>Math.round(v*255).toString(16).padStart(2,'0')).join('');c.fillRect(n.x,n.y,n.w,n.h)}}if(n.color){c.fillStyle=['#e8ecf0','#ffffff','#bec4c9','#e4e6e8'].includes(n.color)?currentUI.settings.textColor:n.color;c.fillRect(n.x,n.y,n.w,n.h)}if(n.stroke)currentUI.box(c,n.x,n.y,n.w,n.h,n.color||'#293640')}
 // Image-filled bordered nodes keep their images; outlines are drawn separately.
 for(const n of layout.items){if(n.type==='TEXT'||!n.stroke||!(n.fills||[]).some(p=>p.type==='IMAGE'))continue;const im=currentUI.assets[n.fills.find(p=>p.type==='IMAGE').hash];currentUI.paint(c,im,n.fills.find(p=>p.type==='IMAGE'),n);c.fillStyle=currentUI.settings.lineColor;c.fillRect(n.x,n.y,n.w,1);c.fillRect(n.x,n.y+n.h-1,n.w,1);c.fillRect(n.x,n.y,1,n.h);c.fillRect(n.x+n.w-1,n.y,1,n.h)}
};
currentUI.hero=(c,key)=>{currentUI.layout(c,key);const texts=currentUI.layouts.find(s=>s.key===key).items.filter(n=>n.type==='TEXT'&&n.text),get=s=>texts.find(n=>n.id.endsWith(s));const name=get(';67:1564'),labels=get(';75:1617'),values=get(';75:1629'),ability=get(';107:1673'),description=get(';79:1631'),s=currentUI.settings;
 currentUI.header(c,'Создание персонажа');currentUI.box(c,7,22,190,188,'#11171c');currentUI.text(c,currentUI.case(name.text),102,24,'center');const ls=labels.text.split('\n').filter(Boolean),vs=values.text.split('\n').filter(Boolean);currentUI.clip(c,8,23,188,186,()=>{ls.forEach((l,i)=>{currentUI.text(c,currentUI.case(l).replace(/:$/,'')+':',7+s.padding,43+i*s.lineStep);currentUI.text(c,vs[i]||'',197-s.padding,43+i*s.lineStep,'right')});const y=43+ls.length*s.lineStep+3,a=ability.text.split('\n');currentUI.text(c,'Каста:',7+s.padding,y);currentUI.text(c,currentUI.case(a[0]),120+s.padding-5,y);currentUI.text(c,'Способность:',7+s.padding,y+s.lineStep);currentUI.text(c,currentUI.case(a[1]),120+s.padding-5,y+s.lineStep);const dy=y+2*s.lineStep+6;currentUI.block(c,description.text.replace(/\s+/g,' '),7,dy,190,210-dy)});for(const n of texts.filter(n=>n.id.endsWith(';3:23')))currentUI.text(c,n.text==='←'?'<':n.text==='→'?'>':currentUI.case(n.text),n.x+n.w/2,217,'center')};
currentUI.base=(c,key)=>{c.imageSmoothingEnabled=false;c.clearRect(0,0,320,240);c.fillStyle='#11171c';c.fillRect(0,0,320,240);
 if(key==='intro5'){c.drawImage(currentUI.intro5Full,0,0);return}
 if(key==='title'){currentUI.layout(c,'title');currentUI.block(c,'Ролевая игра-путешествие\nСерия 1',8,138,304,45,'center');return}
 if(/^hero[012]$/.test(key)){currentUI.hero(c,['hero-wanderer','hero-mage','hero-knight'][Number(key.at(-1))]);return}
 if(['shop3','exchange4'].includes(key)){currentUI.layout(c,key==='shop3'?'merchant':'wanderer');currentUI.header(c,key==='shop3'?'Териберка':'Перевал Геологов');currentUI.slots(c);const cats=key==='shop3'?['Еда','Алкоголь','Рыбалка','Сувениры']:['Обмен','Вещи','Еда','Снаряж.'];cats.forEach((label,i)=>{const x=198+i%2*58,y=40+Math.floor(i/2)*17;currentUI.box(c,x,y,57,16,'#655848');currentUI.text(c,label,x+28.5,y+2,'center')});return}
 const background=currentUI.images[key];if(background){if(!currentUI.backgrounds[key]){const out=document.createElement('canvas');out.width=320;out.height=240;const g=out.getContext('2d');g.drawImage(background,0,0);const data=g.getImageData(0,0,320,240),color=currentUI.settings.lineColor.match(/\w\w/g).map(v=>parseInt(v,16));for(let i=0;i<data.data.length;i+=4)if(data.data[i]===145&&data.data[i+1]===161&&data.data[i+2]===173){for(let j=0;j<3;j++)data.data[i+j]=color[j]}g.putImageData(data,0,0);currentUI.backgrounds[key]=out;}c.drawImage(currentUI.backgrounds[key],0,0);}
 if(['camp1','bear2','house2','village3'].includes(key)){c.fillStyle='#11171c';c.fillRect(7,22,306,212);currentUI.box(c,7,22,190,138);currentUI.box(c,198,22,115,138);currentUI.text(c,'Ситуация',255.5,27,'center');currentUI.controls(c);currentUI.box(c,7,205,190,28,'#11171c');currentUI.resource(c,'Запас сил','80%');currentUI.slots(c);currentUI.header(c,key==='camp1'?'Полуостров Средний':key==='village3'?'Териберка':'Дальние Зеленцы');return}
 const rows=currentUI.rows[key]||[];
 const isStory=rows.some(r=>r.y>=150&&r.w>280)&&!['platform5','drive1','fog4','traffic5','map'].includes(key);
 if(isStory){currentUI.box(c,1,154,318,85,'#11171c');const body=rows.filter(r=>r.y>=150&&r.w>280).map(r=>r.text).join('\n').replace(/\n\s*\n/g,'\n');currentUI.block(c,body,8,164,304,69,'center',currentUI.settings.narratorOffset)}
 for(const r of rows){if(isStory&&r.y>=150&&r.w>280)continue;if(r.y<22&&r.w>200){currentUI.header(c,r.text);continue}const align=(r.align||'LEFT').toLowerCase();currentUI.block(c,currentUI.case(r.text),Math.round(r.x),Math.round(r.y),Math.round(r.w),Math.max(13,Math.round(r.h)),align)}
 c.fillStyle=currentUI.settings.lineColor;c.fillRect(0,0,320,1);c.fillRect(0,239,320,1);c.fillRect(0,0,1,240);c.fillRect(319,0,1,240);
};
